CREATE DATABASE IF NOT EXISTS `foundit_pbl` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `foundit_pbl`;

-- 1. TABEL PENGGUNA (users)
DROP TABLE IF EXISTS `items`;
DROP TABLE IF EXISTS `users`;

CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nim` VARCHAR(50) NOT NULL UNIQUE,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) NULL,
  `phone` VARCHAR(50) NULL,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin', 'mahasiswa') NOT NULL DEFAULT 'mahasiswa',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. TABEL LAPORAN BARANG (items)
CREATE TABLE `items` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama_barang` VARCHAR(255) NOT NULL,
  `kategori` VARCHAR(100) NOT NULL,
  `deskripsi` TEXT NULL,
  `lokasi` VARCHAR(255) NOT NULL,
  `tanggal` VARCHAR(50) NOT NULL,
  `jenis` ENUM('temuan', 'hilang') NOT NULL DEFAULT 'temuan',
  `status` VARCHAR(50) NOT NULL DEFAULT 'aktif',
  `penyimpanan` VARCHAR(255) NOT NULL DEFAULT '-',
  `foto_url` LONGTEXT NULL,
  `pelapor_id` INT NULL,
  `klaim_nama` VARCHAR(150) NULL,
  `klaim_nim` VARCHAR(50) NULL,
  `klaim_kontak` VARCHAR(50) NULL,
  `klaim_bukti` TEXT NULL,
  `klaim_foto` LONGTEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_items_pelapor` FOREIGN KEY (`pelapor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

